-- Generated by pwc2dbt from PowerCenter mapping m_FL_JS_STAGING_FULL, target STG_PRODUCTS.
-- WARNING: suspicious wiring: EXP_PRODUCTS.PRODUCT_PRICE feeds STG_PRODUCTS.PRODUCT_PRICE_CENTS, but EXP_PRODUCTS also has a port named PRODUCT_PRICE_CENTS
-- WARNING: suspicious wiring: EXP_PRODUCTS.PRODUCT_PRICE_CENTS feeds STG_PRODUCTS.PRODUCT_PRICE, but EXP_PRODUCTS also has a port named PRODUCT_PRICE

with

sq_raw_products as (
    -- Source Qualifier SQ_RAW_PRODUCTS
    select
        raw_products.sku,
        raw_products.name,
        raw_products.type,
        raw_products.price,
        raw_products.description
    from {{ source('raw', 'raw_products') }} as raw_products
),

exp_products as (
    -- Expression EXP_PRODUCTS
    select
        sq_raw_products.sku as product_id,
        sq_raw_products.name as product_name,
        sq_raw_products.type as product_type,
        sq_raw_products.price / 100 as product_price,
        sq_raw_products.price as product_price_cents,
        sq_raw_products.description as product_description,
        case when upper(ltrim(rtrim(sq_raw_products.type))) = 'JAFFLE' then 1 else 0 end as is_food_item,
        case when upper(ltrim(rtrim(sq_raw_products.type))) = 'BEVERAGE' then 1 else 0 end as is_drink_item
    from sq_raw_products
)

select
    exp_products.product_id,
    exp_products.product_name,
    exp_products.product_type,
    exp_products.product_price as product_price_cents,
    exp_products.product_price_cents as product_price,
    exp_products.product_description,
    exp_products.is_food_item,
    exp_products.is_drink_item
from exp_products
